import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"What is smtp-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788173818000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-smtp-mcp" tabindex="-1">What is smtp-mcp? <a class="header-anchor" href="#what-is-smtp-mcp" aria-label="Permalink to “What is smtp-mcp?”">​</a></h1><p>smtp-mcp is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server that sends mail over <a href="https://datatracker.ietf.org/doc/html/rfc5321" target="_blank" rel="noreferrer">SMTP</a>. It gives an MCP client — Claude Code, Claude Desktop, Codex — the ability to compose, reply to and forward messages from one configured address, with a person approving each one.</p><h2 id="why-it-is-a-separate-server" tabindex="-1">Why it is a separate server <a class="header-anchor" href="#why-it-is-a-separate-server" aria-label="Permalink to “Why it is a separate server”">​</a></h2><p>Its counterpart, <a href="https://github.com/ni-c/imap-mcp" target="_blank" rel="noreferrer">imap-mcp</a>, reads a mailbox and deliberately cannot send anything. That absence is not a missing feature; it is that server&#39;s entire security argument. An agent is exploitable by indirect prompt injection when three things are true at once: it can reach private data, it processes content an attacker controls, and it can send data somewhere. A mailbox supplies the first two by definition — anyone who knows the address can put text in it — so the third is the one worth removing.</p><p>This server is the third one. It cannot make the same claim, and pretending otherwise would be worse than useless. What it does instead is narrow that channel until an injected instruction has nowhere useful to go, and keep it in a separate process with separate credentials, so that turning on the ability to send does not also hand it a mailbox to read.</p><h2 id="what-constrains-it" tabindex="-1">What constrains it <a class="header-anchor" href="#what-constrains-it" aria-label="Permalink to “What constrains it”">​</a></h2><p>Four things, and none of them is the model:</p><ol><li><strong>It is off.</strong> <code>SMTP_ALLOW_SEND</code> defaults to false. Until it is set, <code>send_mail</code>, <code>reply_mail</code> and <code>forward_mail</code> are not registered at all — absent from <code>tools/list</code>, not refused when called.</li><li><strong>A recipient allowlist.</strong> <code>SMTP_ALLOWED_RECIPIENTS</code> is required to turn sending on. Every address in To, Cc and Bcc is checked before a connection is opened.</li><li><strong>A human confirmation on every message</strong>, through MCP elicitation. The model cannot answer it.</li><li><strong>An hourly cap.</strong> A successful attack is bounded to a number of messages rather than to however long nobody was watching.</li></ol><p>And one thing that is simply absent: there is no <code>from</code> parameter. The sender is <code>SMTP_FROM</code> and nothing else, because a model that could choose its own sender could write in a colleague&#39;s name.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to “What it does not do”">​</a></h2><ul><li><strong>It does not read mail.</strong> That is <a href="https://github.com/ni-c/imap-mcp" target="_blank" rel="noreferrer">imap-mcp</a>.</li><li><strong>It does not sign with DKIM.</strong> A submission server signs for you; a private signing key in an environment variable is a worse trade than it looks.</li><li><strong>It does not let you set arbitrary headers.</strong> Threading uses <code>in_reply_to</code> and <code>references</code>. A generic header passthrough is header injection with extra steps.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — install it and send your first message</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker, mcp-hub</li><li><a href="/guide/configuration">Configuration</a> — every variable, and which tools load</li><li><a href="/guide/security">Security</a> — the trust model and what it does not cover</li></ul>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};